import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
export default function EarningsChart({ data = [], type = 'area' }) { const rows = data.length ? data : Array.from({ length: 6 }, (_, i) => ({ name: `M${i + 1}`, value: (i + 2) * 1200 })); return <div className="h-72 w-full">{type === 'bar' ? <ResponsiveContainer><BarChart data={rows}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis /><Tooltip /><Bar dataKey="value" fill="#C8A84B" /></BarChart></ResponsiveContainer> : <ResponsiveContainer><AreaChart data={rows}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis /><Tooltip /><Area dataKey="value" stroke="#000080" fill="#C8A84B" fillOpacity={0.35} /></AreaChart></ResponsiveContainer>}</div>; }
